    private static final String FALLBACK_DATA = "sst|0|-39600|Pacific/Apia\nhst|0|-36000|Pacific/Honolulu\nakst|0|-32400|America/Anchorage\nakdt|1|-28800|America/Anchorage\npst|0|-28800|America/Los_Angeles\npdt|1|-25200|America/Los_Angeles\nmst|0|-25200|America/Denver\nmdt|1|-21600|America/Denver\ncst|0|-21600|America/Chicago\ncdt|1|-18000|America/Chicago\nest|0|-18000|America/New_York\nvet|0|-16200|America/Caracas\nedt|1|-14400|America/New_York\nast|0|-14400|America/Halifax\nadt|1|-10800|America/Halifax\nbrt|0|-10800|America/Sao_Paulo\nbrst|1|-7200|America/Sao_Paulo\nazost|0|-3600|Atlantic/Azores\nazodt|1|0|Atlantic/Azores\ngmt|0|0|Europe/London\nbst|1|3600|Europe/London\ncet|0|3600|Europe/Paris\ncest|1|7200|Europe/Paris\neet|0|7200|Europe/Helsinki\neest|1|10800|Europe/Helsinki\nmsk|0|10800|Europe/Moscow\nmsd|1|14400|Europe/Moscow\ngst|0|14400|Asia/Dubai\npkt|0|18000|Asia/Karachi\nist|0|19800|Asia/Kolkata\nnpt|0|20700|Asia/Katmandu\nyekt|1|21600|Asia/Yekaterinburg\nnovst|1|25200|Asia/Novosibirsk\nkrat|0|25200|Asia/Krasnoyarsk\ncst|0|28800|Asia/Shanghai\nkrast|1|28800|Asia/Krasnoyarsk\njst|0|32400|Asia/Tokyo\nest|0|36000|Australia/Melbourne\ncst|1|37800|Australia/Adelaide\nest|1|39600|Australia/Melbourne\nnzst|0|43200|Pacific/Auckland\nnzdt|1|46800|Pacific/Auckland";

    public static final List<Entry> TIMEZONE_LOOKUP;
    public static final List<Entry> TIMEZONE_FALLBACKMAP;
    private static final Map<String, List<Entry>> BY_NAME;

    static {
        List<Entry> tzList = new ArrayList<>(1150);
        Map<String, List<Entry>> map = new LinkedHashMap<>();
        for (String chunk : TZ_DATA_CHUNKS) {
            for (String line : chunk.split("\\n")) {
                if (line.isEmpty()) continue;
                String[] parts = line.split("\\|", -1);
                String full = parts[3].isEmpty() ? null : parts[3];
                Entry e = new Entry(parts[0], Integer.parseInt(parts[1]), Integer.parseInt(parts[2]), full);
                tzList.add(e);
                map.computeIfAbsent(e.name.toLowerCase(Locale.ROOT), k -> new ArrayList<>(2)).add(e);
            }
        }
        TIMEZONE_LOOKUP = Collections.unmodifiableList(tzList);
        BY_NAME = Collections.unmodifiableMap(map);

        List<Entry> fbList = new ArrayList<>(50);
        for (String line : FALLBACK_DATA.split("\\n")) {
            if (line.isEmpty()) continue;
            String[] parts = line.split("\\|", -1);
            String full = parts[3].isEmpty() ? null : parts[3];
            fbList.add(new Entry(parts[0], Integer.parseInt(parts[1]), Integer.parseInt(parts[2]), full));
        }
        TIMEZONE_FALLBACKMAP = Collections.unmodifiableList(fbList);
    }

    /** C: {@code abbr_search} */
    public static Entry abbrSearch(String word, long gmtoffset, int isdst) {
        if ("utc".equalsIgnoreCase(word) || "gmt".equalsIgnoreCase(word)) {
            return TIMEZONE_UTC;
        }
        List<Entry> entries = BY_NAME.get(word.toLowerCase(Locale.ROOT));
        if (entries != null && !entries.isEmpty()) {
            Entry firstFound = entries.get(0);
            if (gmtoffset == -1) {
                return firstFound;
            }
            for (Entry e : entries) {
                if (e.gmtoffset == gmtoffset) {
                    return e;
                }
            }
            return firstFound;
        }

        for (Entry fmp : TIMEZONE_FALLBACKMAP) {
            if (fmp.gmtoffset == gmtoffset && fmp.type == isdst) {
                return fmp;
            }
        }
        return null;
    }
